    "enunciado": "O Programa Nacional de Imunizações (PNI) do Brasil, criado em 1973, tem sido um marco na política de saúde pública do país. É importante considerar seu impacto na redução das desigualdades sociais, principalmente a ampliação do acesso à imunização. Sobre as estratégias adotadas pelo PNI e suas implicações sociais, é correto afirmar que:",
