        "texto": "apesar do sucesso na introdução de novas vacinas, o PNI teve um efeito limitado na redução das desigualdades sociais, pois as campanhas de imunização não estavam adequadamente adaptadas às necessidades específicas das populações marginalizadas, como as comunidades quilombolas e as populações indígenas"
