    "enunciado": "A vacina BCG (bacilo de Calmette e Guérin) é apresentada sob a forma liofilizada em ampola multidose, acompanhada da ampola do diluente específico para a vacina. A vacina é preparada com bacilos vivos sendo indicada para prevenir as formas graves da tuberculose (miliar e meníngea). Sobre os cuidados com a vacina da BCG, é correto afirmar:",
