    "enunciado": "O calendário vacinal do Programa Nacional de Imunização (PNI) é dinâmico e sofre atualizações periódicas com base em evidências epidemiológicas, avanços científicos e disponibilidade de novos imunobiológicos. A introdução de uma nova vacina ou a alteração de um esquema vacinal existente exige dos profissionais de saúde, especialmente os enfermeiros, um conhecimento aprofundado não apenas sobre a indicação e a técnica de administração, mas também sobre as particularidades de cada imunobiológico, incluindo suas contraindicações e precauções. Em relação à vacina tríplice viral (sarampo, caxumba e rubéola - SCR), que é uma vacina de vírus vivos atenuados, a principal contraindicação para sua administração em um adulto é:",
    "alternativas": [
      {
        "id": "A",
        "texto": "uso de corticosteroides em dose imunossupressora por tempo prolongado"
      },
      {
        "id": "B",
        "texto": "história prévia de reação alérgica grave a ovo, desde que a reação não tenha sido anafilática"
      },
      {
        "id": "C",
        "texto": "amamentação exclusiva de um lactente saudável"
      },
      {
        "id": "D",
        "texto": "contato recente com pessoa imunodeprimida"
      }
    ],
    "resposta_correta": "A",
    "fundamentacao_correta": "Em conformidade com as diretrizes do Programa Nacional de Imunizações (PNI/Ministério da Saúde), a administração de imunobiológicos, as vias recomendadas, volumes, esquemas preconizados e intervalos mínimos obedecem rigorosamente à resposta imunológica humana e à segurança do usuário. A alternativa [A] ('uso de corticosteroides em dose imunossupressora por tempo prolongado') expressa com exatidão a conduta preconizada pelas normas técnicas oficiais do Ministério da Saúde.",
    "analise_distratores": [
      {
        "letra": "B",
        "motivo": "Incorreta perante os protocolos oficiais do Ministério da Saúde e da banca: 'história prévia de reação alérgica grave a ovo, desde que a reação não tenha sid...' não corresponde à diretriz ou definição válida."
      },
      {
        "letra": "C",
        "motivo": "Incorreta perante os protocolos oficiais do Ministério da Saúde e da banca: 'amamentação exclusiva de um lactente saudável...' não corresponde à diretriz ou definição válida."
      },
      {
        "letra": "D",
        "motivo": "Incorreta perante os protocolos oficiais do Ministério da Saúde e da banca: 'contato recente com pessoa imunodeprimida...' não corresponde à diretriz ou definição válida."
      }
    ],
    "comentario": "Em conformidade com as diretrizes do Programa Nacional de Imunizações (PNI/Ministério da Saúde), a administração de imunobiológicos, as vias recomendadas, volumes, esquemas preconizados e intervalos mínimos obedecem rigorosamente à resposta imunológica humana e à segurança do usuário. A alternativa [A] ('uso de corticosteroides em dose imunossupressora por tempo prolongado') expressa com exatidão a conduta preconizada pelas normas técnicas oficiais do Ministério da Saúde.",
