    "resposta_correta": "E",
    "fundamentacao_correta": "Em conformidade com as diretrizes do Programa Nacional de Imunizações (PNI/Ministério da Saúde), a administração de imunobiológicos, as vias recomendadas, volumes, esquemas preconizados e intervalos mínimos obedecem rigorosamente à resposta imunológica humana e à segurança do usuário. A alternativa [E] ('devem seguir as exigências estabelecidas pela ANVISA e pela FUNASA.') expressa com exatidão a conduta preconizada pelas normas técnicas oficiais do Ministério da Saúde.",
