    "enunciado": "Preto - SP - Técnico em Enfermagem A profilaxia do sarampo está disponível em apresentações diferentes. Todas previnem o sarampo e cabe ao profissional de saúde aplicar a vacina adequada para cada pessoa, de acordo com a idade ou situação epidemiológica. I. Dupla Viral. II. Vacina pentavalente. III. Tríplice viral. IV. Tetra viral. As vacinas que protegem contra o sarampo constam APENAS em",
