    "enunciado": "Preto - SP - Enfermeiro Comparece na Unidade Básica de Saúde uma mãe solicitando que sejam administradas, no seu bebê, vacinas prescritas pelo médico pediatra com esquema diferente do preconizado no Calendário Nacional de Imunização. Nessa situação, a Câmara Técnica do COREN-SP recomenda",
