    "resposta_correta": "C",
    "fundamentacao_correta": "Em conformidade com as diretrizes do Programa Nacional de Imunizações (PNI/Ministério da Saúde), a administração de imunobiológicos, as vias recomendadas, volumes, esquemas preconizados e intervalos mínimos obedecem rigorosamente à resposta imunológica humana e à segurança do usuário. A alternativa [C] ('encaminhar o fato à Coordenação Municipal de Imunizações, para avaliação e orientação.') expressa com exatidão a conduta preconizada pelas normas técnicas oficiais do Ministério da Saúde.",
