    "assunto": "Imunização e Calendário Vacinal (PNI)",
    "enunciado": "Com relação à vacina contra a febre amarela, o profissional de saúde, ao orientar um paciente que pretende viajar com a família para uma área de circulação do vírus, deve esclarecer que I. a vacinação impede a doação de sangue por um período de quatro semanas. II. a dose fracionada da vacina é recomendada para criança a partir de seis meses. III. para pessoas com reação alérgica grave à proteína do ovo é recomendada a dose padrão da vacina. IV. ambas as doses da vacina, padrão e fracionada, são válidas para a emissão do Certificado Internacional da Vacinação contra febre amarela. V. a vacinação é contraindicada para pacientes em tratamento de câncer. Está correto o que consta APENAS em",
