    "comentario": "Em conformidade com as diretrizes do Programa Nacional de Imunizações (PNI/Ministério da Saúde), a administração de imunobiológicos, as vias recomendadas, volumes, esquemas preconizados e intervalos mínimos obedecem rigorosamente à resposta imunológica humana e à segurança do usuário. A alternativa [A] ('ocorra a redução da incidência, enquanto a prevalência pode diminuir de forma gradual ao longo do tempо.') expressa com exatidão a conduta preconizada pelas normas técnicas oficiais do Ministério da Saúde.",
