    "assunto": "Imunização e Calendário Vacinal (PNI)",
    "enunciado": "No primeiro dia da 20ª Campanha Nacional de Vacinação contra a Influenza, uma gestante primigesta com 25 semanas de gestação procurou a unidade para ser vacinada. Nessa situação, o profissional que a atendeu deve",
