    "enunciado": "O Ministério da Saúde publicou que, a partir de janeiro de 2017, passa a disponibilizar a vacina contra o HPV para meninos de 12 a 13 anos na rotina do Calendário Nacional de Vacinação do Sistema Único de Saúde − SUS. Para orientar corretamente a população sobre essa vacinação, os profissionais da saúde devem saber que",
